import { dirname, join, resolve } from "node:path";
import { spawn } from "node:child_process";
import { connect } from "node:net";
import test from "node:test";

const ROOT = resolve(dirname(new URL(import.meta.url).pathname), "..");
const SERVICE = join(ROOT, "src", "serve-inference-socket.mjs");
const CLIENT = join(ROOT, "src", "request-inference-socket.mjs");
const HELPER = join(ROOT, "test", "inference-fabric-harness-helper.mjs");
const pause = (ms) => new Promise((resolvePause) => setTimeout(resolvePause, ms));
const lines = (text) => text.trim() ? text.trim().split("\n").map(JSON.parse) : [];
