  const run = startService(fix, ["--max-line-bytes", "1024"]);
  try {
    assert.equal(await run.ready, true, run.stderr());
    const records = await exchange(fix.socket, [{ control: "shutdown" }, "{broken", "x".repeat(1025), job("still-running")]);
