    assert(records.some((record) => record.refusal?.type === "invalid-json-line"));
    assert(records.some((record) => record.refusal?.type === "line-too-large"));
    assert.equal(records.find((record) => record.id === "still-running")?.text, "helper:fast");
    assert.equal(run.child.exitCode, null);
  } finally { assert.equal((await stopService(run)).code, 0); fix.dispose(); }
