test("connection capacity refuses only excess clients", async () => {
  const fix = fixture([{ id: "only", model: "fast" }]);
  const run = startService(fix, ["--max-connections", "1"]);
  try {
    assert.equal(await run.ready, true, run.stderr());
    const held = connect(fix.socket); let heldOutput = ""; held.setEncoding("utf8").on("data", (chunk) => { heldOutput += chunk; });
    await new Promise((resolveConnect, rejectConnect) => { held.once("connect", resolveConnect); held.once("error", rejectConnect); });
