{
  "kind": "metroplat.contract",
  "id": "inference-fabric-activitystreams-service",
  "scope": "LISS-owned inter-enterprise inference contracting semantics over the persistent cheapest-sufficient broker",
  "actor": "urn:ame:logical-inference-service-section",
  "operations": {
    "solicit-service": {
      "accepts": "ActivityStreams Offer<ServiceSolicitation>{contract,request:InferenceFabricJob}",
      "returns": "ActivityStreams Offer<ExecutableServiceOffer>|Reject<Refusal>",
      "effect": "none",
      "terms": "provider-authored job digest, registry digest, comparable expected resolution consideration, and quoted supplier path"
    },
    "invoke-service": {
      "accepts": "ActivityStreams Accept<ServiceContract>{offer,considerationAcceptance,capability}",
      "returns": "ActivityStreams Accept<InferenceSubmissionResult>|Reject<Refusal>",
      "completion": "the response settles admission only and never waits for provider completion",
      "effect": "provider-local append and one broker.admit call"
    },
    "query-service": {
      "accepts": "ActivityStreams Question<InferenceResultQuery>{id,jobDigest}",
      "returns": "ActivityStreams Accept<InferenceSettlementResult>|Reject<Refusal>",
      "authorization": "the querying actor must be the buyer bound to the admitted contract",
      "providerSpendOnReplay": false
    }
  },
  "invariants": [
    "the adapter shares the one persistent LISS broker and never creates another scheduler",
    "every ingress is exactly addressed to urn:ame:logical-inference-service-section before broker state is read or changed",
    "a provider offer is bound to exact job bytes, comparable consideration, one registry digest, and one buyer",
    "invocation accepts only exact bytes of a provider-issued offer plus an actor-bound attenuated capability",
    "broker admission is asynchronous and returns an immediate typed receipt",
