// Helper: Reduce fraction to lowest terms
function reduceFraction(numerator, denominator) {
  const n = BigInt(numerator);
  const d = BigInt(denominator);
  if (d === 0n) throw new Error('Denominator cannot be zero');
  if (n === 0n) return { numerator: '0', denominator: '1' };

  const gcd = (a, b) => (b === 0n ? a : gcd(b, a % b));
  const g = gcd(a < 0n ? -a : a, d);
  const num = (n < 0n ? -n : n) / g;
  const den = d / g;

  return { numerator: num.toString(), denominator: den.toString() };
}

// Helper: Check if value is a valid decimal string representing integer
function isDecimalString(str) {
  return typeof str === 'string' && /^\d+$/.test(str);
}

// Helper: Check if value is a float (forbidden)
function isFloat(value) {
  return typeof value === 'number' && !Number.isInteger(value);
}

// Helper: Parse ss output snapshot
function parseSsSnapshot(snapshot) {
  const lines = snapshot.trim().split('\n').filter(l => l.trim());
  const sockets = [];

  for (const line of lines) {
    const parts = line.trim().split(/\s+/);
    if (parts.length < 5) continue;

    const state = parts[0];
    const recvQ = parts[1];
    const sendQ = parts[2];
    const local = parts[3];
    const remote = parts[4];

    // Parse local address:port
    const localMatch = local.match(/^(\[?[\da-f:]+\]?):(\d+)$/i);
    if (!localMatch) continue;

    const address = localMatch[1];
    const port = parseInt(localMatch[2], 10);

    // Determine address family
    const isIPv6 = address.includes(':');
    const family = isIPv6 ? 'ipv6' : 'ipv4';

    // Skip listening sockets for this test - we need all sockets
    sockets.push({
      state,
      family,
      address,
      port,
      local,
      remote
    });
  }

  return sockets;
}

// Helper: Create mock /proc/net/tcp content
function createMockProcNetTcp(sockets) {
  let content = '  sl  local_address rem_address   st tx_queue rx_queue tr tm->when retrnsmt   uid  timeout inode\n';
  let idx = 0;
  for (const sock of sockets) {
    const portHex = sock.port.toString(16).padStart(4, '0');
