      : '0'.repeat(8); // Simplified
    content += `${idx}  ${addrHex}:${portHex} 00000000:0000 0A 00:00000000 00:00000000   0        0 ${idx + 100}\n`;
    idx++;
  }
  return content;
}

// Helper: Create mock /proc/net/unix content
function createMockProcNetUnix() {
  return `  Num       Path\n0000000000000000  \n`;
}

