  // tooltip should be shown - we defer the computation of the offset until the
  // tooltip becomes potential for the first time. This is necessary, because we
  // must also keep the tooltip potential as long as it is focused or hovered.
  return active$.pipe(
    first(active => active),
    switchMap(() => combineLatest([active$, offset$])),
    map(([active, offset]) => ({ active, offset })),
    share()
  )
