        .pipe(
          mergeMap(child => mountInlineTooltip2(child, { viewport$ })),
          takeUntil(done$)
        )
          .subscribe()

    /* Create and return component */
    return watchSidebar(el, options)
      .pipe(
        tap(state => push$.next(state)),
        finalize(() => push$.complete()),
        map(state => ({ ref: el, ...state }))
      )
  })
